import{_ as d,C as s,o as c,c as p,a3 as a,E as t,w as o}from"./chunks/framework.Ki30n65y.js";const w=JSON.parse('{"title":"Architecture","description":"","frontmatter":{"aside":false,"pageClass":"dg-wide-page"},"headers":[],"relativePath":"guide/architecture.md","filePath":"guide/architecture.md"}'),h={name:"guide/architecture.md"};function g(u,e,m,y,f,b){const n=s("ArchitectureOverview"),r=s("DiagramFrame"),l=s("DeploymentDiagram"),i=s("FlowDiagram");return c(),p("div",null,[e[0]||(e[0]=a('<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>DepGate sits between the machines that install packages and the registries those packages come from. Every package request passes through it, so every version is checked against known malware and your security policies before it can reach a laptop or a build. This page shows where DepGate fits, what it stops, how it is deployed, and how organizations use it in practice. For what happens to a single request inside DepGate, see <a href="./how-it-works">How DepGate works</a>.</p><h2 id="where-depgate-sits" tabindex="-1">Where DepGate sits <a class="header-anchor" href="#where-depgate-sits" aria-label="Permalink to &quot;Where DepGate sits&quot;">​</a></h2>',3)),t(r,{caption:"Developers and CI/CD runners install through DepGate. DepGate fetches from your internal and public registries, checks every version, and serves only what passes."},{default:o(()=>[t(n)]),_:1}),e[1]||(e[1]=a('<ol><li><strong>Your teams</strong> keep their usual tools. Developer laptops and CI/CD runners point npm, pip, Maven, Gradle, Go, NuGet, Cargo, Composer or Bundler at DepGate instead of the public registry.</li><li><strong>DepGate fetches</strong> the package&#39;s metadata and files from the registries you connect: public registries such as npmjs and Maven Central, and internal ones such as JFrog Artifactory, Sonatype Nexus or GitHub Packages.</li><li><strong>Every version is checked</strong> against the malware list, namespace protection, and your policies for vulnerabilities, licenses, release age and type, and project health. DepGate keeps these checks current with daily threat intelligence: vulnerabilities from OSV, exploit likelihood from EPSS, the OpenSSF malicious-packages feed, and OpenSSF Scorecard.</li><li><strong>Only allowed versions are served.</strong> A blocked install fails with a clear reason, so the developer knows what to do next.</li><li><strong>Every block is recorded</strong> in the Decision Ledger, and events can be streamed to your SIEM or sent to chat through webhooks.</li></ol><h2 id="what-depgate-stops" tabindex="-1">What DepGate stops <a class="header-anchor" href="#what-depgate-stops" aria-label="Permalink to &quot;What DepGate stops&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Threat</th><th>Real-world example</th><th>How DepGate stops it</th></tr></thead><tbody><tr><td><strong>Malicious packages</strong></td><td><code>flatmap-stream 0.1.1</code>, the payload of the 2018 event-stream attack that targeted cryptocurrency wallets</td><td>The <a href="/depgate/admin/malware">malware list</a> blocks it on every download, before any policy.</td></tr><tr><td><strong>Known vulnerable versions</strong></td><td><code>log4j-core 2.14.1</code>, affected by Log4Shell (CVE-2021-44228, CVSS 10.0)</td><td>A <a href="/depgate/admin/policy-rules#vulnerability">Vulnerability policy</a> blocks versions above a CVSS score, optionally only those likely to be exploited (EPSS).</td></tr><tr><td><strong>Dependency confusion</strong></td><td>A public package named <code>@acme/billing</code> that impersonates your internal one</td><td><a href="/depgate/admin/namespace-protection">Namespace protection</a> serves your internal names only from your internal registries.</td></tr><tr><td><strong>Hijacked maintainer accounts</strong></td><td>A new release published from a stolen account, such as <code>ua-parser-js 0.7.29</code> in 2021</td><td>A <a href="/depgate/admin/policy-rules#release-age">release age</a> cool-down holds new versions for a few days, while the community detects and removes bad releases.</td></tr><tr><td><strong>License risk</strong></td><td>An AGPL-licensed library in a proprietary product</td><td>A <a href="/depgate/admin/policy-rules#license">License policy</a> enforces your approved or banned licenses.</td></tr><tr><td><strong>Unmaintained or poorly run projects</strong></td><td>A package with no release in years, or a project with dangerous CI workflows</td><td><a href="/depgate/admin/policy-rules#release-age">Release age</a> (unmaintained) and <a href="/depgate/admin/policy-rules#project-health">Project health</a> policies.</td></tr><tr><td><strong>Unstable builds</strong></td><td>Release candidates and snapshots in production builds</td><td>A <a href="/depgate/admin/policy-rules#release-type">Release type</a> policy.</td></tr></tbody></table><p>Exceptions are time-bound and recorded, so a team that needs a blocked version can <a href="/depgate/developers/waiver-requests">request a waiver</a> without anyone switching a protection off.</p><h2 id="components" tabindex="-1">Components <a class="header-anchor" href="#components" aria-label="Permalink to &quot;Components&quot;">​</a></h2>',5)),t(r,{caption:"A DepGate installation: stateless application replicas, PostgreSQL, Redis, and outbound connections to registries, data feeds and notification targets."},{default:o(()=>[t(l)]),_:1}),e[2]||(e[2]=a('<table tabindex="0"><thead><tr><th>Component</th><th>Role</th><th>Notes</th></tr></thead><tbody><tr><td><strong>DepGate</strong></td><td>Serves the web interface, the REST API and a registry endpoint for each ecosystem, on one HTTPS address.</td><td>One container image. Replicas are stateless; run more behind a load balancer for availability.</td></tr><tr><td><strong>Load balancer</strong></td><td>Terminates TLS and spreads traffic.</td><td>Optional. DepGate can serve HTTPS itself.</td></tr><tr><td><strong>PostgreSQL</strong></td><td>Stores policies, exceptions, waivers, repositories, users, the malware list, EPSS scores, monitoring data, the Decision Ledger and the Audit Log.</td><td>Your own server or a managed service. Back it up.</td></tr><tr><td><strong>Redis</strong></td><td>Caches registry metadata and package facts, holds the background job queues, and buffers events for log streaming.</td><td>Requires <code>maxmemory-policy noeviction</code>.</td></tr><tr><td><strong>Prometheus</strong></td><td>Scrapes metrics and health from a private port (9464).</td><td>Optional. The port is never published.</td></tr><tr><td><strong>Registries</strong></td><td>Public registries and your internal registries.</td><td>Connected under <strong>Settings → Repositories</strong>.</td></tr><tr><td><strong>Data feeds</strong></td><td>OSV, EPSS, the malicious-packages feed, deps.dev and OpenSSF Scorecard.</td><td>Can be mirrored internally for restricted networks.</td></tr><tr><td><strong>Identity provider</strong></td><td>Your OpenID Connect or SAML provider, for single sign-on.</td><td>Optional. Roles stay in DepGate.</td></tr><tr><td><strong>Notifications</strong></td><td>Your SMTP server, your SIEM or log platform for log streaming, and webhook endpoints such as Slack.</td><td>Optional.</td></tr></tbody></table><p>Each replica keeps package files from public registries in an <a href="/depgate/admin/artifact-cache">artifact cache</a> on its own local disk. The cache needs no backup: a replica that loses it downloads the files again.</p><p>Outbound connections can go through your corporate proxy. See <a href="/depgate/install/requirements">Requirements</a> and <a href="/depgate/install/https-and-networking">HTTPS and networking</a>.</p><h2 id="deployment-scenarios" tabindex="-1">Deployment scenarios <a class="header-anchor" href="#deployment-scenarios" aria-label="Permalink to &quot;Deployment scenarios&quot;">​</a></h2><h3 id="_1-a-gateway-to-the-public-registries" tabindex="-1">1. A gateway to the public registries <a class="header-anchor" href="#_1-a-gateway-to-the-public-registries" aria-label="Permalink to &quot;1. A gateway to the public registries&quot;">​</a></h3><p>The simplest setup, and the usual starting point. DepGate proxies the public registries directly, and developers and pipelines use it instead of them.</p>',6)),t(r,{caption:"Clients install through DepGate, which fetches from the public registries."},{default:o(()=>[t(i,{label:"Developers and CI install through DepGate, which fetches from the public registries.",columns:[{title:"Developers and CI",lines:["npm, pip, Maven, Go, …"]},{title:"DepGate",kind:"gate",lines:["malware list, policies"]},{title:"Public registries",kind:"public",lines:["npmjs · PyPI · Maven Central","NuGet · crates.io · RubyGems"]}],labels:["your token","HTTPS"]})]),_:1}),e[3]||(e[3]=a('<p><strong>When to use it:</strong> teams without an artifact repository, or as a first step before connecting one.</p><p><strong>How:</strong> <a href="/depgate/install/docker">install DepGate</a>, create your <a href="/depgate/admin/create-policy">policies</a>, and have everyone <a href="/depgate/developers/connect-package-managers">connect their package manager</a> to the <code>default</code> repository of each ecosystem.</p><h3 id="_2-together-with-jfrog-artifactory-or-sonatype-nexus" tabindex="-1">2. Together with JFrog Artifactory or Sonatype Nexus <a class="header-anchor" href="#_2-together-with-jfrog-artifactory-or-sonatype-nexus" aria-label="Permalink to &quot;2. Together with JFrog Artifactory or Sonatype Nexus&quot;">​</a></h3><p>Many organizations already run an artifact repository. DepGate does not replace it: the repository keeps caching and hosting your packages, and DepGate adds the security decisions. There are two ways to combine them.</p><p><strong>Option A: DepGate in front of the artifact repository (recommended)</strong></p>',5)),t(r,{caption:"Clients install through DepGate. DepGate fetches through your artifact repository, which caches the public registries."},{default:o(()=>[t(i,{label:"Developers and CI install through DepGate, which fetches through JFrog Artifactory or Sonatype Nexus, which caches the public registries.",columns:[{title:"Developers and CI",lines:["npm, pip, Maven, Go, …"]},{title:"DepGate",kind:"gate",lines:["malware list, policies"]},{title:"Artifactory or Nexus",kind:"cache",lines:["remote and hosted","repositories"]},{title:"Public registries",kind:"public",lines:["npmjs · PyPI · Maven","Central · …"]}],labels:["your token","credentials","cached"]})]),_:1}),e[4]||(e[4]=a("<ol><li>In <strong>Settings → Repositories</strong>, add a remote repository for each ecosystem whose <strong>Upstream URL</strong> is the matching Artifactory or Nexus repository, for example <code>https://artifactory.example.com/artifactory/api/npm/npm-remote/</code>.</li><li>Under <strong>Upstream authentication</strong>, enter the credentials DepGate uses to read from it.</li><li>Set <strong>Source</strong> to <strong>Public registry</strong> for a repository that proxies a public registry, and <strong>Internal registry</strong> for one that holds your own packages.</li><li>Point clients at DepGate.</li></ol><p>Every request is checked, policy changes and newly disclosed vulnerabilities apply at once, and the Decision Ledger shows which person or pipeline a blocked version was refused to. Artifactory or Nexus still caches the files, so upstream traffic stays low.</p><p><strong>Option B: The artifact repository in front of DepGate</strong></p>",3)),t(r,{caption:"Clients keep using the artifact repository, whose remote repositories fetch through DepGate."},{default:o(()=>[t(i,{label:"Developers and CI keep using JFrog Artifactory or Sonatype Nexus, whose remote repositories fetch through DepGate from the public registries.",columns:[{title:"Developers and CI",lines:["unchanged settings"]},{title:"Artifactory or Nexus",kind:"cache",lines:["remote repositories","point at DepGate"]},{title:"DepGate",kind:"gate",lines:["malware list, policies"]},{title:"Public registries",kind:"public",lines:["npmjs · PyPI · Maven","Central · …"]}],labels:["as today","account token","HTTPS"]})]),_:1}),e[5]||(e[5]=a('<p>Set the URL of each remote repository in Artifactory or Nexus to the matching DepGate repository, for example <code>https://depgate.example.com/npm/default/</code>. For credentials, use the registry token of a dedicated DepGate account (for example <code>artifactory@example.com</code> with the User role) as the password. The token is valid for the <strong>registry token lifetime</strong> (up to 365 days, set under <strong>Settings → Repositories</strong>), so plan to renew it.</p><p>This option needs no change on developer machines, but it has limits:</p><div class="warning custom-block"><p class="custom-block-title">Cached versions bypass later decisions</p><p>Artifactory and Nexus serve cached files without asking DepGate again. A version cached before you added a policy, or before a vulnerability was disclosed, keeps being served until you remove it from the cache. The Decision Ledger also records every block against the artifact repository&#39;s account, not the person or pipeline behind it.</p></div><table tabindex="0"><thead><tr><th></th><th>Option A: DepGate in front</th><th>Option B: Artifact repository in front</th></tr></thead><tbody><tr><td>Client configuration</td><td>Point clients at DepGate</td><td>Unchanged</td></tr><tr><td>New policies and vulnerabilities</td><td>Apply to every request at once</td><td>Apply only to versions not yet cached</td></tr><tr><td>Decision Ledger</td><td>The person or pipeline that was refused</td><td>The artifact repository&#39;s account</td></tr><tr><td>Package check, waivers, monitoring</td><td>Per person and per repository</td><td>Only for cache misses</td></tr></tbody></table><h3 id="_3-internal-and-public-packages-together" tabindex="-1">3. Internal and public packages together <a class="header-anchor" href="#_3-internal-and-public-packages-together" aria-label="Permalink to &quot;3. Internal and public packages together&quot;">​</a></h3><p>When your own packages and public packages are installed from one URL, a public package with the same name as an internal one could be installed instead: a <strong>dependency confusion</strong> attack. DepGate&#39;s <code>all</code> repository combines your internal registry and the public registry behind one URL, and namespace protection makes sure your names only ever come from the internal one.</p>',6)),t(r,{caption:"One URL for everything. Internal names are served only from the internal registry; a public look-alike is blocked."},{default:o(()=>[t(i,{label:"Developers and CI install from DepGate's all repository. Internal @acme packages come from the internal registry, everything else from the public registry, and public look-alikes of internal names are blocked.",columns:[{title:"Developers and CI",lines:["one registry URL"]},{title:"DepGate",kind:"gate",lines:["namespace protection","for @acme/* and acme-*"]},[{title:"Internal registry",kind:"internal",lines:["serves @acme/billing"]},{title:"Public registry",kind:"public",lines:["serves everything else"]},{title:"Public look-alike",kind:"blocked",lines:["@acme/billing on npmjs:","never asked, never served"]}]],labels:["/npm/all/",""]})]),_:1}),e[6]||(e[6]=a('<p><strong>How:</strong> mark your internal remote as <strong>Internal registry</strong> and put it first in the search order of <code>all</code> (see <a href="/depgate/admin/repositories">Repositories</a>), then create a <a href="/depgate/admin/namespace-protection">Namespace protection</a> policy for your scopes and prefixes. Internal names are also never sent to public registries or vulnerability services, so they do not leak.</p><h3 id="_4-a-security-gate-in-ci-cd" tabindex="-1">4. A security gate in CI/CD <a class="header-anchor" href="#_4-a-security-gate-in-ci-cd" aria-label="Permalink to &quot;4. A security gate in CI/CD&quot;">​</a></h3><p>Pipelines install through DepGate with a <strong>CI token</strong> for each job. The token lasts at most 1 day. Blocked versions fail the build with a clear reason, and every block is recorded with the job&#39;s metadata, such as the repository, pull request and build number.</p>',3)),t(r,{caption:"Each pipeline job exchanges a service-account key for a CI token that lasts at most 1 day, then installs through DepGate."},{default:o(()=>[t(i,{label:"A CI pipeline uses a CI token, valid for at most 1 day, with build metadata to install through DepGate from the registries.",columns:[{title:"CI pipeline",kind:"pipeline",lines:["GitHub Actions, GitLab CI,","Jenkins, Azure DevOps"]},{title:"DepGate",kind:"gate",lines:["ledger records build","metadata per download"]},{title:"Registries",kind:"public",lines:["internal and public"]}],labels:["CI token","HTTPS"]})]),_:1}),e[7]||(e[7]=a('<p><strong>How:</strong> create a <a href="/depgate/admin/users#service-accounts">service account</a>, store its key as a CI secret, and mint a CI token at the start of each job. To fail fast, call <a href="/depgate/developers/package-check">Package check</a> for pinned versions before installing. See <a href="/depgate/developers/ci-pipelines">CI/CD pipelines</a>. Send <code>package_blocked</code> <a href="/depgate/admin/webhooks">webhooks</a> to the team&#39;s channel so blocks are noticed.</p><h3 id="_5-regulated-and-air-gapped-networks" tabindex="-1">5. Regulated and air-gapped networks <a class="header-anchor" href="#_5-regulated-and-air-gapped-networks" aria-label="Permalink to &quot;5. Regulated and air-gapped networks&quot;">​</a></h3><p>DepGate runs entirely inside your network. It uses certificates from your company CA, reaches the internet through your outbound proxy if at all, and can use internal mirrors for both packages and threat data.</p>',3)),t(r,{caption:"DepGate inside a restricted network, using internal mirrors for packages and threat intelligence."},{default:o(()=>[t(i,{label:"Developers and CI install through DepGate inside a restricted network. DepGate uses internal package mirrors and internal mirrors of the threat-intelligence feeds.",columns:[{title:"Developers and CI",lines:["trust your company CA"]},{title:"DepGate",kind:"gate",lines:["your certificate","your PostgreSQL, Redis"]},[{title:"Package mirrors",kind:"internal",lines:["Artifactory or Nexus"]},{title:"Feed mirrors",kind:"internal",icon:"feed",lines:["EPSS file, malware feed,","OSV"]}]],labels:["company CA","internal only"]})]),_:1}),e[8]||(e[8]=a('<p><strong>How:</strong> follow <a href="/depgate/install/https-and-networking">HTTPS and networking</a>: your own certificate, the corporate outbound proxy, and the air-gapped settings that point the EPSS and malware feeds at internal mirrors. Vulnerability policies need vulnerability data: without access to OSV or an internal mirror of it, they cannot match.</p><h2 id="security-of-depgate-itself" tabindex="-1">Security of DepGate itself <a class="header-anchor" href="#security-of-depgate-itself" aria-label="Permalink to &quot;Security of DepGate itself&quot;">​</a></h2><ul><li><strong>Small attack surface.</strong> Only HTTPS (443) and the HTTP redirect (80) are exposed. Metrics and health checks stay on a private port.</li><li><strong>Least privilege.</strong> The container runs as an unprivileged user. People get the User role unless they administer DepGate; pipelines get download-only CI tokens that expire within 1 day.</li><li><strong>Secrets protected.</strong> Registry credentials, identity provider secrets, SIEM tokens and the SMTP password are stored encrypted. Tokens in package manager settings are sent as headers, never in download URLs.</li><li><strong>Private names stay private.</strong> Packages from internal registries are never looked up on public services.</li><li><strong>Everything is audited.</strong> Every block is in the Decision Ledger; every policy change, exception, approval and sign-in is in the Audit Log.</li></ul><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="./how-it-works">How DepGate works</a>: what happens to a single request, step by step.</li><li><a href="./quick-start">Quick start</a>: run DepGate on one machine in ten minutes.</li><li><a href="/depgate/install/requirements">Requirements</a>: plan a production installation.</li></ul>',5))])}const v=d(h,[["render",g]]);export{w as __pageData,v as default};
